        }
        if ((v >= 26) && (v < 52)) {
            emon.Port.TextCp(t, 71 + v);
        }
        if ((v >= 52) && (v < 62)) {
            emon.Port.TextCp(t, v - 4);
        }
        if (v == 62) {
            emon.Port.TextCp(t, 43);
        }
        if (v == 63) {
            emon.Port.TextCp(t, 47);
        }
        return 0;
    }
    internal static int HB64(System.Text.StringBuilder t, emon.Port.Buf abytes, int start, int ln) {
        // RFC 4648 base64 (standard alphabet, padded, no line breaks) of abytes[start, start+ln).
        int i = 0;
        int b0 = 0;
        int b1 = 0;
        int b2 = 0;
        while (i < ln) {
            b0 = emon.Port.BufAt(abytes, start + i);
            b1 = 0;
            b2 = 0;
            if ((i + 1) < ln) {
                b1 = emon.Port.BufAt(abytes, start + (i + 1));
            }
            if ((i + 2) < ln) {
                b2 = emon.Port.BufAt(abytes, start + (i + 2));
            }
            HB64Char(t, b0 / 4);
            HB64Char(t, ((b0 % 4) * 16) + (b1 / 16));
            if ((i + 1) < ln) {
                HB64Char(t, ((b1 % 16) * 4) + (b2 / 64));
            } else {
                emon.Port.TextCp(t, 61);
            }
            if ((i + 2) < ln) {
                HB64Char(t, b2 % 64);
            } else {
                emon.Port.TextCp(t, 61);
            }
            i += 3;
        }
        return 0;
    }
    internal static int HHasCaption(emon.Port.Cells nodes, int n) {
        int c = Model.NodeFirstChild(nodes, n);
        while (c >= 0) {
            if (Model.NodeKind(nodes, c) == Model.NkCaption()) {
                return 1;
            }
            c = Model.NodeNext(nodes, c);
        }
        return 0;
    }
    internal static int HAltEmpty(emon.Port.Cells nodes, emon.Port.Cells attrs, int n) {
        // 1 when the placeholder's accessible name is empty: a figure with no `alt`. A seal always has its word.
        int a = HTattr(nodes, attrs, n, Model.FkAlt());
        if (Model.NodeKind(nodes, n) == Model.NkSeal()) {
            return 0;
        }
        if (a < 0) {
            return 1;
        }
        if (Model.AttrLen(attrs, a) == 0) {
            return 1;
        }
        return 0;
    }
    internal static int HAlt(System.Text.StringBuilder t, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, int n) {
        // The text the placeholder's `aria-label` would have had: a figure's `alt`, a seal's `Stamp: ...` label (D069).
        int a = HTattr(nodes, attrs, n, Model.FkAlt());
        int b = -1;
        if (Model.NodeKind(nodes, n) == Model.NkFigure()) {
            if (a >= 0) {
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
            }
            return 0;
        }
        b = HTattr(nodes, attrs, n, Model.FkName());
        HSealWord(t, Model.NodeSub(nodes, n));
        if ((Model.NodeHasText(nodes, n) == 1) || (b >= 0)) {
            emon.Port.TextAscii(t, ": ");
        }
        if (Model.NodeHasText(nodes, n) == 1) {
            HRun(t, text, Model.NodeTextStart(nodes, n), Model.NodeTextLen(nodes, n));
        }
        if ((Model.NodeHasText(nodes, n) == 0) && (b >= 0)) {
            HRun(t, text, Model.AttrValue(attrs, b), Model.AttrLen(attrs, b));
        }
        return 0;
    }
    internal static int HPx(int cpt) {
        // A length in centipoints as CSS pixels: cpt * 4 / 300 rounded half up, at least 1.
        int v = ((cpt * 8) + 300) / 600;
        if (v < 1) {
            return 1;
        }
        return v;
    }
    internal static int HImg(System.Text.StringBuilder t, int o, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, emon.Port.Cells assets, emon.Port.Cells uses, emon.Port.Buf abytes, emon.Port.Cells prefix, int n, int id) {
        // The `<img>` of node n's asset `id`: src, alt, width and height (the node's own use: the size the picture had on the
        // page), `data-emon-asset`, and `data-emon-alt=missing` when there is no alt and no caption to be the description.
        int u = Model.AssetUseHead(assets, id);
        int w = 1;
        int h = 1;
        int i = 0;
        while (u >= 0) {
            if (Model.UseNode(uses, u) == n) {
                w = HPx(Model.UseX1(uses, u) - Model.UseX0(uses, u));
                h = HPx(Model.UseY1(uses, u) - Model.UseY0(uses, u));
                u = -1;
            } else {
                u = Model.UseNext(uses, u);
            }
        }
        emon.Port.TextAscii(t, "<img src=\"");
        if (HOn(o, 512) == 1) {
            while (i < emon.Port.CellsLen(prefix)) {
                HCp(t, emon.Port.CellsAt(prefix, i));
                i += 1;
            }
            emon.Port.TextAscii(t, "a");
            emon.Port.TextI32(t, id);
            if (Model.AssetType(assets, id) == 1) {
                emon.Port.TextAscii(t, ".jpg");
            }
            if (Model.AssetType(assets, id) != 1) {
                emon.Port.TextAscii(t, ".png");
            }
        } else {
            emon.Port.TextAscii(t, "data:");
            Model.AmtEmitName(t, Model.AssetType(assets, id));
            emon.Port.TextAscii(t, ";base64,");
            HB64(t, abytes, Model.AssetBstart(assets, id), Model.AssetBlen(assets, id));
        }
        emon.Port.TextAscii(t, "\" alt=\"");
        HAlt(t, nodes, attrs, text, n);
        emon.Port.TextAscii(t, "\" width=\"");
        emon.Port.TextI32(t, w);
        emon.Port.TextAscii(t, "\" height=\"");
        emon.Port.TextI32(t, h);
        emon.Port.TextAscii(t, "\" data-emon-asset=\"");
        emon.Port.TextI32(t, id);
        emon.Port.TextAscii(t, "\"");
        if ((HAltEmpty(nodes, attrs, n) == 1) && (HHasCaption(nodes, n) == 0)) {
            emon.Port.TextAscii(t, " data-emon-alt=\"missing\"");
        }
        emon.Port.TextAscii(t, ">");
        return 0;
    }
    internal static int HBlocks(System.Text.StringBuilder t, int o, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells pages, emon.Port.Cells layout, emon.Port.Cells text, emon.Port.Cells assets, emon.Port.Cells uses, emon.Port.Buf abytes, emon.Port.Cells prefix, int n, int d) {
        // Every non-inline child of n as a block at depth d. Answers how many
        // wrote anything (a milestone turned off writes nothing).
        int c = Model.NodeFirstChild(nodes, n);
        int k = 0;
        while (c >= 0) {
            if (Model.NodeIsInline(nodes, c) == 0) {
                k += HBlock(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, c, d);
            }
            c = Model.NodeNext(nodes, c);
        }
        return k;
    }
    internal static int HBody(System.Text.StringBuilder t, int o, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells pages, emon.Port.Cells layout, emon.Port.Cells text, emon.Port.Cells assets, emon.Port.Cells uses, emon.Port.Buf abytes, emon.Port.Cells prefix, int n, int d) {
        // What goes inside a block's element: its line of text (inline
        // children, else its own run), then its block children at depth d.
        // Answers how many block children were written, so the caller knows
        // whether its closing tag starts a new line (pretty mode).
        HInner(t, o, nodes, attrs, regions, pages, layout, text, n);
        return HBlocks(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d);
    }
    internal static int HListType(System.Text.StringBuilder t, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, int n) {
        // An ordered list's `type` from its scheme: `lower-alpha` a,
        // `upper-alpha` A, `lower-roman` i, `upper-roman` I (`decimal` and
        // anything else: none, the default is decimal). The scheme names are
        // 11 characters, told apart by the first and the seventh.
        int a = HTattr(nodes, attrs, n, Model.FkScheme());
        int c0 = 0;
        int c6 = 0;
        if (a < 0) {
            return 0;
        }
        if (Model.AttrLen(attrs, a) != 11) {
            return 0;
        }
        c0 = emon.Port.CellsAt(text, Model.AttrValue(attrs, a));
        c6 = emon.Port.CellsAt(text, Model.AttrValue(attrs, a) + 6);
        if ((c0 == 108) && (c6 == 97)) {
            emon.Port.TextAscii(t, " type=\"a\"");
        }
        if ((c0 == 117) && (c6 == 97)) {
            emon.Port.TextAscii(t, " type=\"A\"");
        }
        if ((c0 == 108) && (c6 == 114)) {
            emon.Port.TextAscii(t, " type=\"i\"");
        }
        if ((c0 == 117) && (c6 == 114)) {
            emon.Port.TextAscii(t, " type=\"I\"");
        }
        return 0;
    }
    internal static int HBlock(System.Text.StringBuilder t, int o, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells pages, emon.Port.Cells layout, emon.Port.Cells text, emon.Port.Cells assets, emon.Port.Cells uses, emon.Port.Buf abytes, emon.Port.Cells prefix, int n, int d) {
        // One node as a block element at depth d (SPEC 5.1), on its own line
        // in pretty mode. Answers 1 if it wrote anything, 0 if not. An inline
        // kind met where a block belongs is written as itself.
        int kind = Model.NodeKind(nodes, n);
        int sub = Model.NodeSub(nodes, n);
        int hb = 0;
        int a = -1;
        int b = -1;
        int c = 0;
        int lv = 0;
        int pk = 0;
        int asid = -1;
        if (Model.NodeIsInline(nodes, n) == 1) {
            HNl(t, o, d);
            HInline(t, o, nodes, attrs, regions, pages, layout, text, n);
            return 1;
        }
        if (kind == Model.NkBreak()) {
            if (HOn(o, 64) == 1) {
                return 0;
            }
            HNl(t, o, d);
            HMilestone(t, o, nodes, attrs, regions, pages, layout, text, n);
            return 1;
        }
        HNl(t, o, d);
        if (kind == Model.NkSection()) {
            emon.Port.TextAscii(t, "<section");
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = HBody(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</section>");
            return 1;
        }
        if (kind == Model.NkHeading()) {
            lv = sub;
            if (lv < 1) {
                lv = 1;
            }
            pk = lv;
            if (pk > 6) {
                pk = 6;
            }
            emon.Port.TextAscii(t, "<h");
            emon.Port.TextI32(t, pk);
            if (lv > 6) {
                emon.Port.TextAscii(t, " aria-level=\"");
                emon.Port.TextI32(t, lv);
                emon.Port.TextAscii(t, "\"");
            }
            a = HTattr(nodes, attrs, n, Model.FkNumber());
            if (a >= 0) {
                emon.Port.TextAscii(t, " data-emon-number=\"");
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            HAlignAttr(t, o, nodes, attrs, n);
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            if (a >= 0) {
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                emon.Port.TextAscii(t, " ");
            }
            hb = HBody(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</h");
            emon.Port.TextI32(t, pk);
            emon.Port.TextAscii(t, ">");
            return 1;
        }
        if (kind == Model.NkParagraph()) {
            emon.Port.TextAscii(t, "<p");
            HAlign(t, o, sub);
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = HBody(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</p>");
            return 1;
        }
        if (kind == Model.NkList()) {
            if (sub == 2) {
                emon.Port.TextAscii(t, "<ol");
                a = HIattr(nodes, attrs, n, Model.FkStart());
                if (a >= 0) {
                    emon.Port.TextAscii(t, " start=\"");
                    emon.Port.TextI32(t, Model.AttrValue(attrs, a));
                    emon.Port.TextAscii(t, "\"");
                }
                HListType(t, nodes, attrs, text, n);
            }
            if (sub != 2) {
                emon.Port.TextAscii(t, "<ul");
            }
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = HBody(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            if (sub == 2) {
                emon.Port.TextAscii(t, "</ol>");
            }
            if (sub != 2) {
                emon.Port.TextAscii(t, "</ul>");
            }
            return 1;
        }
        if (kind == Model.NkItem()) {
            emon.Port.TextAscii(t, "<li");
            a = HIattr(nodes, attrs, n, Model.FkValue());
            if (a >= 0) {
                emon.Port.TextAscii(t, " value=\"");
                emon.Port.TextI32(t, Model.AttrValue(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            a = HTattr(nodes, attrs, n, Model.FkMarker());
            if (a >= 0) {
                emon.Port.TextAscii(t, " data-emon-marker=\"");
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = HBody(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</li>");
            return 1;
        }
        if (kind == Model.NkTable()) {
            emon.Port.TextAscii(t, "<table");
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            c = Model.NodeFirstChild(nodes, n);
            while (c >= 0) {
                if (Model.NodeKind(nodes, c) == Model.NkCaption()) {
                    HBlock(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, c, d + 1);
                }
                c = Model.NodeNext(nodes, c);
            }
            c = Model.NodeFirstChild(nodes, n);
            while (c >= 0) {
                if (Model.NodeKind(nodes, c) != Model.NkCaption()) {
                    HBlock(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, c, d + 1);
                }
                c = Model.NodeNext(nodes, c);
            }
            HNl(t, o, d);
            emon.Port.TextAscii(t, "</table>");
            return 1;
        }
        if (kind == Model.NkRowgroup()) {
            if (sub == 1) {
                emon.Port.TextAscii(t, "<thead");
            }
            if (sub == 3) {
                emon.Port.TextAscii(t, "<tfoot");
            }
            if ((sub != 1) && (sub != 3)) {
                emon.Port.TextAscii(t, "<tbody");
            }
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = HBlocks(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            if (sub == 1) {
                emon.Port.TextAscii(t, "</thead>");
            }
            if (sub == 3) {
                emon.Port.TextAscii(t, "</tfoot>");
            }
            if ((sub != 1) && (sub != 3)) {
                emon.Port.TextAscii(t, "</tbody>");
            }
            return 1;
        }
        if (kind == Model.NkRow()) {
            emon.Port.TextAscii(t, "<tr");
            if (sub == 1) {
                emon.Port.TextAscii(t, " data-emon-repeated=\"true\"");
            }
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = HBlocks(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</tr>");
            return 1;
        }
        if (kind == Model.NkCell()) {
            if (sub > 0) {
                emon.Port.TextAscii(t, "<th scope=\"");
                Model.ChEmitName(t, sub);
                emon.Port.TextAscii(t, "\"");
            }
            if (sub <= 0) {
                emon.Port.TextAscii(t, "<td");
            }
            a = HIattr(nodes, attrs, n, Model.FkRowspan());
            if ((a >= 0) && (Model.AttrValue(attrs, a) != 1)) {
                emon.Port.TextAscii(t, " rowspan=\"");
                emon.Port.TextI32(t, Model.AttrValue(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            a = HIattr(nodes, attrs, n, Model.FkColspan());
            if ((a >= 0) && (Model.AttrValue(attrs, a) != 1)) {
                emon.Port.TextAscii(t, " colspan=\"");
                emon.Port.TextI32(t, Model.AttrValue(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            HAlignAttr(t, o, nodes, attrs, n);
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = HBody(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            if (sub > 0) {
                emon.Port.TextAscii(t, "</th>");
            }
            if (sub <= 0) {
                emon.Port.TextAscii(t, "</td>");
            }
            return 1;
        }
        if (kind == Model.NkCaption()) {
            pk = 0;
            a = Model.NodeParent(nodes, n);
            if (a >= 0) {
                pk = Model.NodeKind(nodes, a);
            }
            if (pk == Model.NkTable()) {
                emon.Port.TextAscii(t, "<caption");
            }
            if (pk == Model.NkFigure()) {
                emon.Port.TextAscii(t, "<figcaption");
            }
            if ((pk != Model.NkTable()) && (pk != Model.NkFigure())) {
                emon.Port.TextAscii(t, "<p data-emon=\"caption\"");
            }
            a = HTattr(nodes, attrs, n, Model.FkLabel());
            if (a >= 0) {
                emon.Port.TextAscii(t, " data-emon-label=\"");
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            HAlignAttr(t, o, nodes, attrs, n);
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = HBody(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            if (pk == Model.NkTable()) {
                emon.Port.TextAscii(t, "</caption>");
            }
            if (pk == Model.NkFigure()) {
                emon.Port.TextAscii(t, "</figcaption>");
            }
            if ((pk != Model.NkTable()) && (pk != Model.NkFigure())) {
                emon.Port.TextAscii(t, "</p>");
            }
            return 1;
        }
        if (kind == Model.NkFigure()) {
            asid = HAssetId(nodes, attrs, n, o);
            emon.Port.TextAscii(t, "<figure data-emon-kind=\"");
            if (sub > 0) {
                Model.FgEmitName(t, sub);
            }
            if (sub <= 0) {
                emon.Port.TextAscii(t, "unknown");
            }
            emon.Port.TextAscii(t, "\"");
            if (asid < 0) {
                emon.Port.TextAscii(t, " role=\"img\"");
                a = HTattr(nodes, attrs, n, Model.FkAlt());
                if (a >= 0) {
                    emon.Port.TextAscii(t, " aria-label=\"");
                    HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                    emon.Port.TextAscii(t, "\"");
                }
            }
            a = HTattr(nodes, attrs, n, Model.FkLabel());
            if (a >= 0) {
                emon.Port.TextAscii(t, " data-emon-label=\"");
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            HNoasset(t, o, nodes, attrs, n);
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = 0;
            if (asid >= 0) {
                HNl(t, o, d + 1);
                HImg(t, o, nodes, attrs, text, assets, uses, abytes, prefix, n, asid);
                hb = 1;
            }
            HInner(t, o, nodes, attrs, regions, pages, layout, text, n);
            a = Model.NodeAttr(nodes, attrs, n, Model.FkLabels());
            while (a >= 0) {
                emon.Port.TextAscii(t, "<span data-emon=\"label\">");
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                emon.Port.TextAscii(t, "</span>");
                a = Model.AttrFindNext(attrs, a, Model.FkLabels());
            }
            hb += HBlocks(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</figure>");
            return 1;
        }
        if (kind == Model.NkSeal()) {
            asid = HAssetId(nodes, attrs, n, o);
            emon.Port.TextAscii(t, "<figure data-emon-kind=\"");
            if (sub > 0) {
                Model.SlEmitName(t, sub);
            }
            if (sub <= 0) {
                emon.Port.TextAscii(t, "seal");
            }
            emon.Port.TextAscii(t, "\"");
            a = HTattr(nodes, attrs, n, Model.FkName());
            if (a >= 0) {
                emon.Port.TextAscii(t, " data-emon-name=\"");
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            b = HTattr(nodes, attrs, n, Model.FkDate());
            if (b >= 0) {
                emon.Port.TextAscii(t, " data-emon-date=\"");
                HRun(t, text, Model.AttrValue(attrs, b), Model.AttrLen(attrs, b));
                emon.Port.TextAscii(t, "\"");
            }
            b = HTattr(nodes, attrs, n, Model.FkColor());
            if (b >= 0) {
                emon.Port.TextAscii(t, " data-emon-color=\"");
                HRun(t, text, Model.AttrValue(attrs, b), Model.AttrLen(attrs, b));
                emon.Port.TextAscii(t, "\"");
            }
            if (asid < 0) {
                emon.Port.TextAscii(t, " role=\"img\" aria-label=\"");
                HAlt(t, nodes, attrs, text, n);
                emon.Port.TextAscii(t, "\"");
            }
            HNoasset(t, o, nodes, attrs, n);
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            if (asid >= 0) {
                HNl(t, o, d + 1);
                HImg(t, o, nodes, attrs, text, assets, uses, abytes, prefix, n, asid);
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</figure>");
            return 1;
        }
        if (kind == Model.NkFormula()) {
            emon.Port.TextAscii(t, "<figure data-emon-kind=\"formula\"");
            if (sub > 0) {
                emon.Port.TextAscii(t, " data-emon-display=\"");
                Model.DpEmitName(t, sub);
                emon.Port.TextAscii(t, "\"");
            }
            emon.Port.TextAscii(t, " aria-label=\"");
            HPlain(t, nodes, text, n);
            emon.Port.TextAscii(t, "\"");
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, "></figure>");
            return 1;
        }
        if (kind == Model.NkCode()) {
            emon.Port.TextAscii(t, "<pre");
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, "><code>");
            HInner(t, o, nodes, attrs, regions, pages, layout, text, n);
            emon.Port.TextAscii(t, "</code>");
            hb = HBlocks(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</pre>");
            return 1;
        }
        if (kind == Model.NkQuote()) {
            emon.Port.TextAscii(t, "<blockquote");
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = HBody(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</blockquote>");
            return 1;
        }
        if (kind == Model.NkNote()) {
            if ((sub == 6) || (sub == 9)) {
                emon.Port.TextAscii(t, "<aside data-emon-role=\"");
                Model.RlEmitName(t, sub);
                emon.Port.TextAscii(t, "\"");
                if (HTargeted(nodes, attrs, n) == 1) {
                    emon.Port.TextAscii(t, " id=\"fn-");
                    emon.Port.TextI32(t, n);
                    emon.Port.TextAscii(t, "\"");
                }
            }
            if (sub == 5) {
                emon.Port.TextAscii(t, "<aside role=\"doc-endnote\" id=\"fn-");
            }
            if ((sub != 5) && (sub != 6) && (sub != 9)) {
                emon.Port.TextAscii(t, "<aside role=\"doc-footnote\" id=\"fn-");
            }
            if ((sub != 6) && (sub != 9)) {
                emon.Port.TextI32(t, n);
                emon.Port.TextAscii(t, "\"");
            }
            a = HTattr(nodes, attrs, n, Model.FkMarker());
            if (a >= 0) {
                emon.Port.TextAscii(t, " data-emon-marker=\"");
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            hb = HBody(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</aside>");
            return 1;
        }
        if (kind == Model.NkField()) {
            emon.Port.TextAscii(t, "<span data-emon=\"field\"");
            a = HTattr(nodes, attrs, n, Model.FkName());
            if (a >= 0) {
                emon.Port.TextAscii(t, " data-emon-name=\"");
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            a = HTattr(nodes, attrs, n, Model.FkType());
            if (a >= 0) {
                emon.Port.TextAscii(t, " data-emon-type=\"");
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
                emon.Port.TextAscii(t, "\"");
            }
            a = HIattr(nodes, attrs, n, Model.FkChecked());
            if (a >= 0) {
                if (Model.AttrValue(attrs, a) != 0) {
                    emon.Port.TextAscii(t, " data-emon-checked=\"true\"");
                }
                if (Model.AttrValue(attrs, a) == 0) {
                    emon.Port.TextAscii(t, " data-emon-checked=\"false\"");
                }
            }
            HCommon(t, o, nodes, regions, pages, layout, n);
            emon.Port.TextAscii(t, ">");
            a = HTattr(nodes, attrs, n, Model.FkValue());
            if (a >= 0) {
                HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
            }
            if (a < 0) {
                HInner(t, o, nodes, attrs, regions, pages, layout, text, n);
            }
            emon.Port.TextAscii(t, "</span>");
            return 1;
        }
        if (kind == Model.NkFurniture()) {
            HFurnitureOpen(t, o, nodes, attrs, regions, pages, layout, text, n);
            if (Model.NodeHasText(nodes, n) == 1) {
                HNl(t, o, d + 1);
                emon.Port.TextAscii(t, "<p>");
                HRun(t, text, Model.NodeTextStart(nodes, n), Model.NodeTextLen(nodes, n));
                emon.Port.TextAscii(t, "</p>");
                hb = 1;
            }
            hb += HBlocks(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
            if (hb > 0) {
                HNl(t, o, d);
            }
            emon.Port.TextAscii(t, "</aside>");
            return 1;
        }
        emon.Port.TextAscii(t, "<div data-emon-kind=\"");
        Model.NkEmitName(t, kind);
        emon.Port.TextAscii(t, "\"");
        HCommon(t, o, nodes, regions, pages, layout, n);
        emon.Port.TextAscii(t, ">");
        hb = HBody(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, n, d + 1);
        if (hb > 0) {
            HNl(t, o, d);
        }
        emon.Port.TextAscii(t, "</div>");
        return 1;
    }
    internal static int HFurnitureOpen(System.Text.StringBuilder t, int o, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells pages, emon.Port.Cells layout, emon.Port.Cells text, int n) {
        // `<aside data-emon="furniture" data-emon-role="header" ...>`:
        // the role, the pages it was seen on, then the options' attributes.
        int sub = Model.NodeSub(nodes, n);
        int a = Model.NodeAttr(nodes, attrs, n, Model.FkPages());
        int i = 0;
        emon.Port.TextAscii(t, "<aside data-emon=\"furniture\"");
        if (sub > 0) {
            emon.Port.TextAscii(t, " data-emon-role=\"");
            Model.RlEmitName(t, sub);
            emon.Port.TextAscii(t, "\"");
        }
        if (a >= 0) {
            emon.Port.TextAscii(t, " data-emon-pages=\"");
            while (a >= 0) {
                if (i > 0) {
                    emon.Port.TextAscii(t, " ");
                }
                emon.Port.TextI32(t, Model.AttrValue(attrs, a));
                i += 1;
                a = Model.AttrFindNext(attrs, a, Model.FkPages());
            }
            emon.Port.TextAscii(t, "\"");
        }
        HCommon(t, o, nodes, regions, pages, layout, n);
        emon.Port.TextAscii(t, ">");
        return 0;
    }
    internal static int HMeta(System.Text.StringBuilder t, int o, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, int key) {
        // `<meta name="author" content="...">` for a root attribute: the
        // name is the JSON key's spelling (`author`, `created`, ...).
        int a = HTattr(nodes, attrs, 0, key);
        if (a < 0) {
            return 0;
        }
        HNl(t, o, 2);
        emon.Port.TextAscii(t, "<meta name=\"");
        Model.FkEmitName(t, key);
        emon.Port.TextAscii(t, "\" content=\"");
        HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
        emon.Port.TextAscii(t, "\">");
        return 1;
    }
    public static int HtmlEmit(System.Text.StringBuilder t, int opts, int confBelow, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells ledger, emon.Port.Cells layout, emon.Port.Cells assets, emon.Port.Cells uses, emon.Port.Buf abytes, emon.Port.Cells prefix) {
        // Write the Model as HTML (SPEC 5). `opts` is an OR of `ho-*`;
        // `conf-below` is the threshold for `ho-confidence` (nodes with a
        // conf under it get `data-emon-conf`). The root (node 0) must be a
        // document: run `model-check` first on a Model of unknown origin.
        // Answers 0.
        int o = (opts & 4095) + (confBelow * 4096);
        int nn = Model.NodeCount(nodes);
        int nl = Model.LedgerCount(ledger);
        int a = -1;
        int i = 0;
        emon.Port.TextAscii(t, "<!doctype html>");
        HNl(t, o, 0);
        emon.Port.TextAscii(t, "<html");
        a = HTattr(nodes, attrs, 0, Model.FkLang());
        if (a >= 0) {
            emon.Port.TextAscii(t, " lang=\"");
            HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
            emon.Port.TextAscii(t, "\"");
        }
        emon.Port.TextAscii(t, ">");
        HNl(t, o, 1);
        emon.Port.TextAscii(t, "<head>");
        HNl(t, o, 2);
        emon.Port.TextAscii(t, "<meta charset=\"utf-8\">");
        HNl(t, o, 2);
        emon.Port.TextAscii(t, "<title>");
        a = HTattr(nodes, attrs, 0, Model.FkTitle());
        if (a >= 0) {
            HRun(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
        }
        emon.Port.TextAscii(t, "</title>");
        HMeta(t, o, nodes, attrs, text, Model.FkGenerator());
        HMeta(t, o, nodes, attrs, text, Model.FkAuthor());
        HMeta(t, o, nodes, attrs, text, Model.FkSubject());
        HMeta(t, o, nodes, attrs, text, Model.FkKeywords());
        HMeta(t, o, nodes, attrs, text, Model.FkCreator());
        HMeta(t, o, nodes, attrs, text, Model.FkProducer());
        HMeta(t, o, nodes, attrs, text, Model.FkCreated());
        HMeta(t, o, nodes, attrs, text, Model.FkModified());
        HNl(t, o, 1);
        emon.Port.TextAscii(t, "</head>");
        HNl(t, o, 1);
        emon.Port.TextAscii(t, "<body>");
        HNl(t, o, 2);
        emon.Port.TextAscii(t, "<main>");
        if (HOn(o, 32) == 0) {
            i = 0;
            while (i < nn) {
                if ((Model.NodeKind(nodes, i) == Model.NkFurniture()) && (Model.NodeParent(nodes, i) == -1)) {
                    HBlock(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, i, 3);
                }
                i += 1;
            }
        }
        HBlocks(t, o, nodes, attrs, regions, pages, layout, text, assets, uses, abytes, prefix, 0, 3);
        if (HOn(o, 8) == 1) {
            i = 0;
            while (i < nl) {
                HNl(t, o, 3);
                emon.Port.TextAscii(t, "<template data-emon=\"dropped\" data-emon-reason=\"");
                Model.DrEmitName(t, Model.LedgerReason(ledger, i));
                emon.Port.TextAscii(t, "\" data-emon-page=\"");
                emon.Port.TextI32(t, Model.LedgerPage(ledger, i));
                emon.Port.TextAscii(t, "\">");
                if (Model.LedgerTextStart(ledger, i) >= 0) {
                    HRun(t, text, Model.LedgerTextStart(ledger, i), Model.LedgerTextLen(ledger, i));
                }
                emon.Port.TextAscii(t, "</template>");
                i += 1;
            }
        }
        HNl(t, o, 2);
        emon.Port.TextAscii(t, "</main>");
        HNl(t, o, 1);
        emon.Port.TextAscii(t, "</body>");
        HNl(t, o, 0);
        emon.Port.TextAscii(t, "</html>");
        return 0;
    }
}
